<script setup>
import { ref } from 'vue'
const left=ref(30),right=ref(70),levels=[0,30,70,100],message=ref('')
function test(){message.value='Vibration test requested. Connect a supported device and use Expert mode to apply device settings.';setTimeout(()=>message.value='',4000)}
</script>
<template><section class="panel-card visual-tuning"><div class="panel-heading"><div><span class="eyebrow">马达与体感</span><h3>Haptic intensity</h3></div><button class="btn primary" @click="test">测试震动</button></div><div class="motor-grid"><article v-for="motor in [{name:'Left grip',value:left},{name:'Right grip',value:right}]" :key="motor.name" class="motor-card"><div class="motor-icon">ϟ</div><span class="eyebrow">{{motor.name}}</span><strong>{{motor.value}}%</strong><div class="levels"><button v-for="level in levels" :key="level" class="btn" :class="{primary:motor.value===level}" @click="motor.name==='Left grip'?left=level:right=level">{{level===0?'Off':level+'%'}}</button></div><input v-if="motor.name==='Left grip'" v-model.number="left" type="range" min="0" max="100"><input v-else v-model.number="right" type="range" min="0" max="100"></article></div><p v-if="message" class="hint test-message">{{message}}</p><p class="hint">Intensity controls are visual controls; device write support depends on the connected controller and existing Expert settings.</p></section></template>
<style scoped>.visual-tuning{margin-bottom:16px}.motor-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.motor-card{display:flex;flex-direction:column;align-items:flex-start;gap:11px;padding:18px;border:1px solid #334155;border-radius:13px;background:linear-gradient(145deg,#162238,#101827)}.motor-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:#064e3b55;color:#34d399;font-size:22px}.motor-card strong{font-size:28px;color:#67e8f9}.levels{display:flex;gap:6px;flex-wrap:wrap}.levels .btn{padding:5px 9px;font-size:9px}.motor-card input[type=range]{width:100%;accent-color:#34d399}.test-message{color:#34d399;margin:8px 0}@media(max-width:600px){.motor-grid{grid-template-columns:1fr}}</style>